head.script:
scwin.onpageload = function() {
    scwin.data1 = [
        "0", "A", 1,
        "0", "A", 2,
        "0", "A", 3
    ];
    dataList1.setData(scwin.data1.slice(0));
}
scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    return false;
    //				return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var row = dataList1.getTotalRow();
    for (var i = 0; i < row; i++) {
        console.log(i + " ::::: " + dataList1.getCellData(i, 'col3'));
    }
};
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_oncellclick = function(row, col) {
    var rrowIdx = dataList1.getRealRowIndex(row);
    console.log('gridview getFocusedRowIndex');
    console.log(grid1.getFocusedRowIndex());
    console.log('getCellData >> focusedRowIndex : ' + dataList1.getCellData(grid1.getFocusedRowIndex(), col));
    console.log('getRowJSON >> focusedRowIndex : ');
    console.log(dataList1.getRowJSON(grid1.getFocusedRowIndex()));
}
scwin.formatter = function(data) {
    console.log(data);
};
scwin.trigger2_onclick = function(e) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_header3', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.checkValue = function(id1, id2) {
    if (WebSquare.wUnit.getDomById(id1)) {
        return WebSquare.wUnit.getJq("#" + id1).text();
    } else if (WebSquare.wUnit.getDomById(id2)) {
        return WebSquare.wUnit.getJq("#" + id2).text();
    }
    return "";
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].checked == false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '분류2'항목을 groupby 시킨다.
    //1. After executing the sample, groupby the 'Classification 2' item.
    //Verify step 1. The 'Category 2' item is groupby.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue('_headerRowNumber', '_headerRowNumber_bodyRow_0') == 'A [ 3 건 ] '", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '분류2'항목을 클릭하여 필터리스트의 'A'값을 체크해제하고 다시 체크했을때 '전체선택'도 함께 변경되는지 확인한다.
    //2. Click the 'Category 2' item to uncheck the 'A' value in the filter list, and when you check again, make sure that 'Select All' also changes.
    //Verify step 2. 'Unselect All' is also unchecked and checked.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 29-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
